{
  "spec": "Build a 32-bit adder/subtractor using two 16-bit adders (add16). The top_module takes 32-bit inputs a and b and a 1-bit sub signal. When sub=0, compute a+b. When sub=1, compute a-b by inverting all 32 bits of b (XOR with sub replicated to 32 bits) and adding 1 via the low carry-in. Split a and the modified b into low 16 bits and high 16 bits. Feed the low parts and sub as carry-in to the first add16. Connect its carry-out to the carry-in of the second add16 which adds the high parts. Combine the two 16-bit sums into the 32-bit output sum.",
  "given_sv": "module add16(input [15:0] a, input [15:0] b, input cin, output [15:0] sum, output cout);
endmodule",
  "ref_sv": "module RefModule(input [31:0] a, input [31:0] b, input sub, output [31:0] sum);
  assign sum = sub ? a - b : a + b;
endmodule",
  "solution_sv": "module top_module(input [31:0] a, input [31:0] b, input sub, output [31:0] sum);
  wire [31:0] b_xor;
  assign b_xor = b ^ {32{sub}};

  wire [15:0] sum_low, sum_high;
  wire carry_low;

  add16 low_adder (
    .a    (a[15:0]),
    .b    (b_xor[15:0]),
    .cin  (sub),
    .sum  (sum_low),
    .cout (carry_low)
  );

  add16 high_adder (
    .a    (a[31:16]),
    .b    (b_xor[31:16]),
    .cin  (carry_low),
    .sum  (sum_high),
    .cout ()
  );

  assign sum = {sum_high, sum_low};
endmodule",
  "directed": [
    {"a": 5, "b": 3, "sub": 0},
    {"a": 5, "b": 3, "sub": 1},
    {"a": 0, "b": 0, "sub": 0},
    {"a": 0, "b": 0, "sub": 1},
    {"a": 4294967295, "b": 1, "sub": 0},
    {"a": 4294967295, "b": 1, "sub": 1},
    {"a": 2147483648, "b": 2147483648, "sub": 0},
    {"a": 2147483648, "b": 2147483648, "sub": 1}
  ],
  "hints": {
    "L0": "Think about how two's complement subtraction (a - b) can be done by inverting b and adding 1.",
    "L3": "Replicate sub to 32 bits and XOR with b to get b_xor. Split a and b_xor into low 16 bits (15:0) and high 16 bits (31:16). Instantiate the first add16 with a[15:0], b_xor[15:0], cin=sub. Connect its cout to the cin of the second add16 which takes a[31:16] and b_xor[31:16]. Concatenate the two sums (high then low) to form the 32-bit sum."
  },
  "common_mistakes": [
    "Forgetting to replicate sub to 32 bits before XOR, causing only the LSB of b to be inverted.",
    "Using sub as carry-in for the high adder instead of the low adder's carry-out.",
    "Swapping the order of concatenation (putting low sum in high bits).",
    "Not connecting the carry chain between the two add16 instances."
  ]
}

